; Materia: Lenguajes de Interfaz ; Alumno: Luis Arnoldo Cervantes ; Horario: [10-11] ; Docente: Dr. José Luis Medina Jiménez ; Práctica: 3. Comparación y prueba ; Descripción: Simula un login numérico comparando entradas con un PIN establecido y límite de intentos.INCLUDE Irvine32.inc.data    msgPIN BYTE "INGRESE EL PIN DE ACCESO: ",0    msgERROR BYTE "PIN INCORRECTO: ",0    msgACCESO BYTE "PIN CORRECTO ",0    msgINTENTOS BYTE "INTENTOS RESTANTES :",0    msgBLOQUEO BYTE "SISTEMA BLOQUEADO POR 9861762587 AÑOS: ",0    PinCorrecto = 6767.codemain PROC	mov ebx, 3 ; Numero de intentosciclo:	mov edx, OFFSET msgPIN	call WriteString	call ReadInt		cmp eax, PinCorrecto	je acceso		mov edx, OFFSET msgERROR	call WriteString		dec ebx	jz bloqueado		mov edx, OFFSET msgINTENTOS	call WriteString		mov eax, ebx	call WriteDec	call Crlf	jmp cicloacceso:	mov edx, OFFSET msgACCESO	call WriteString	call Crlf	jmp finbloqueado:	mov edx, OFFSET msgBLOQUEO	call WriteString	call Crlf	jmp finfin:	exitmain ENDPEND main